({editor:e}=createMultiLineEditor('a\nb\nc')); sendKeys(e,['g','J','.']); console.log('gJ', JSON.stringify(e.getText()));
({editor:e}=createEditorWithSpy('abc')); sendKeys(e,['r','Z','l','.']); console.log('r', JSON.stringify(e.getText()));
({editor:e}=createEditorWithSpy('foo bar baz')); sendKeys(e,['d','i','w','.']); console.log('diw', JSON.stringify(e.getText()));
